div.script:
document.addEventListener("DOMContentLoaded", function () {
    let wrzFormGroup = {}, wrzFormCheck = 0;

    function wrzTryFormChecking() {
        if (wrzFormCheck < 30) {
            const roleTypeInputs = document.querySelectorAll(".hs-input[name='role_type']");
            if (roleTypeInputs.length) {
                roleTypeInputs.forEach(function (input) {
                    const inputId = input.getAttribute("id");

                    if (!wrzFormGroup[inputId]) {
                        wrzFormGroup[inputId] = 1;

                        input.addEventListener("change", function () {
                            const pickedVal = input.value;
                            const parentDiv = input.closest("form.hs-form");
                            const containerDiv = input.closest(".form-columns-1");
                            const containerDivAlt = input.closest(".form-columns-2");

                            if (pickedVal === "Patient") {
                                parentDiv.querySelectorAll(".form-columns-1, .form-columns-2, .hs-submit, .field").forEach(el => el.classList.add("disableWRZform"));
                                containerDiv?.classList.remove("disableWRZform");

                                const myRoleField = parentDiv.querySelector(".hs_role_type");
                                myRoleField?.classList.remove("disableWRZform");

                                if (!wrzFormGroup[inputId + "-setup"]) {
                                    wrzFormGroup[inputId + "-setup"] = 1;
                                    const helpText = `
This form is intended for healthcare professionals. For patient support related topics, please visit our FAQ page.`;

                                    if (containerDiv) {
                                        containerDiv.insertAdjacentHTML("afterend", helpText);
                                    } else {
                                        input.insertAdjacentHTML("afterend", helpText);
                                    }
                                } else {
                                    const helpElement = document.getElementById("help-" + inputId);
                                    if (helpElement) helpElement.style.display = "";
                                }

                                if (!containerDiv) {
                                    containerDivAlt?.classList.remove("disableWRZform");
                                    containerDivAlt?.querySelectorAll(".hs-fieldtype-text").forEach(el => el.classList.add("disableWRZform"));
                                }

                                const emailInput = parentDiv.querySelector('input[name="email"]');
                                if (emailInput) emailInput.value = "";
                            } else {
                                if (wrzFormGroup[inputId + "-setup"] === 1) {
                                    const helpElement = document.getElementById("help-" + inputId);
                                    if (helpElement) helpElement.style.display = "none";
                                }

                                parentDiv.querySelectorAll(".form-columns-1, .form-columns-2, .field, .hs-submit").forEach(el => el.classList.remove("disableWRZform"));

                                if (containerDivAlt) {
                                    containerDivAlt.querySelectorAll(".hs-fieldtype-text").forEach(el => el.classList.remove("disableWRZform"));
                                }
                            }
                        });
                    }
                });
            }

            wrzFormCheck += 1;
            setTimeout(wrzTryFormChecking, wrzFormCheck > 10 ? 100 : 20);
        }
    }

    wrzTryFormChecking();
});
